package quebec.culture.donnees;

import android.app.*;import android.content.*;import android.graphics.*;import android.graphics.pdf.PdfDocument;import android.net.Uri;import android.os.*;import android.widget.*;import java.io.*;import java.text.SimpleDateFormat;import java.util.*;

public class PdfExportActivity extends Activity{
 private static final int CREATE_PDF=4701; private byte[] pending;
 @Override public void onCreate(Bundle b){super.onCreate(b);Ui.bars(this);LinearLayout r=Ui.root(this);r.addView(Ui.text(this,"Dossier PDF",27,true));r.addView(Ui.text(this,"Génère un PDF lisible du projet avec les informations enregistrées dans l’application, les indicateurs des catalogues, le budget, l’équipe, l’échéancier et les pièces justificatives.",13,false));Button create=Ui.primary(this,"Créer le PDF du dossier");create.setOnClickListener(v->createPdf());r.addView(create);Button zip=Ui.secondary(this,"Exporter aussi le ZIP complet");zip.setOnClickListener(v->startActivity(new Intent(this,ExportPackageActivity.class)));r.addView(zip);r.addView(Ui.text(this,"Ce PDF est un document de préparation interne. Les formulaires, gabarits et règles officiels demeurent la référence pour le dépôt.",12,false));setContentView(Ui.wrap(this,r));}
 private void createPdf(){try{pending=buildPdf();Intent i=new Intent(Intent.ACTION_CREATE_DOCUMENT);i.addCategory(Intent.CATEGORY_OPENABLE);i.setType("application/pdf");String d=new SimpleDateFormat("yyyy-MM-dd_HHmm",Locale.CANADA_FRENCH).format(new Date());i.putExtra(Intent.EXTRA_TITLE,"Culture-du-Quebec-dossier-"+d+".pdf");startActivityForResult(i,CREATE_PDF);}catch(Exception e){Toast.makeText(this,"Erreur PDF : "+e.getMessage(),Toast.LENGTH_LONG).show();}}
 @Override protected void onActivityResult(int req,int res,Intent data){super.onActivityResult(req,res,data);if(req!=CREATE_PDF||res!=RESULT_OK||data==null||data.getData()==null||pending==null)return;Uri u=data.getData();try(OutputStream out=getContentResolver().openOutputStream(u)){out.write(pending);out.flush();Toast.makeText(this,"PDF enregistré",Toast.LENGTH_LONG).show();}catch(Exception e){Toast.makeText(this,"Impossible d’enregistrer : "+e.getMessage(),Toast.LENGTH_LONG).show();}finally{pending=null;}}
 private byte[] buildPdf()throws Exception{PdfDocument pdf=new PdfDocument();ArrayList<String> lines=reportLines();int pageNo=1,index=0;while(index<lines.size()){PdfDocument.PageInfo pi=new PdfDocument.PageInfo.Builder(595,842,pageNo).create();PdfDocument.Page page=pdf.startPage(pi);Canvas c=page.getCanvas();Paint p=new Paint(Paint.ANTI_ALIAS_FLAG);p.setColor(Color.rgb(24,42,58));float y=54;p.setTypeface(Typeface.create(Typeface.DEFAULT,Typeface.BOLD));p.setTextSize(pageNo==1?22:15);c.drawText(pageNo==1?"Culture du Québec — Dossier de préparation":"Culture du Québec — Dossier (suite)",42,y,p);y+=28;p.setTypeface(Typeface.create(Typeface.DEFAULT,Typeface.NORMAL));p.setTextSize(10);p.setColor(Color.rgb(75,88,100));c.drawText("Généré le "+new SimpleDateFormat("yyyy-MM-dd HH:mm",Locale.CANADA_FRENCH).format(new Date())+" · Page "+pageNo,42,y,p);y+=26;while(index<lines.size()&&y<795){String line=lines.get(index++);if(line.startsWith("## ")){y+=8;p.setTypeface(Typeface.create(Typeface.DEFAULT,Typeface.BOLD));p.setTextSize(14);p.setColor(Color.rgb(6,79,137));c.drawText(line.substring(3),42,y,p);y+=22;}else if(line.startsWith("# ")){y+=6;p.setTypeface(Typeface.create(Typeface.DEFAULT,Typeface.BOLD));p.setTextSize(17);p.setColor(Color.rgb(24,42,58));c.drawText(line.substring(2),42,y,p);y+=24;}else{p.setTypeface(Typeface.create(Typeface.DEFAULT,Typeface.NORMAL));p.setTextSize(10.5f);p.setColor(Color.rgb(34,46,56));for(String w:wrap(line,86)){c.drawText(w,48,y,p);y+=15;if(y>=795)break;}if(line.isEmpty())y+=4;}}
pdf.finishPage(page);pageNo++;}ByteArrayOutputStream out=new ByteArrayOutputStream();pdf.writeTo(out);pdf.close();return out.toByteArray();}
 private ArrayList<String> reportLines(){ArrayList<String> s=new ArrayList<>();SharedPreferences plan=getSharedPreferences("standardisation_plan",0),budget=getSharedPreferences("budget",0),team=getSharedPreferences("team_capacity",0),timeline=getSharedPreferences("timeline",0),check=getSharedPreferences("application_checklist",0),pieces=getSharedPreferences("supporting_docs",0);String[] standards={"MétaMusique","Arts de la scène","Cinéma","Livre — éditeurs","Exposition dans un contexte muséal"};int si=Math.max(0,Math.min(4,plan.getInt("standard",0)));s.add("# Résumé du projet");s.add("Organisation : "+plan.getString("org","—"));s.add("Norme / secteur : "+standards[si]);s.add("Responsable des données : "+plan.getString("resp","—"));s.add("Sources / provenance : "+plan.getString("sources","—"));s.add("Contrôle qualité : "+plan.getString("quality","—"));s.add("Partage / données ouvertes : "+plan.getString("sharing","—"));s.add("Sauvegardes / conservation : "+plan.getString("backup","—"));s.add("Cible mesurable : "+plan.getString("target","—"));s.add("Échéancier global : "+plan.getString("schedule","—"));s.add("");s.add("## Catalogues et traçabilité");List<DocumentStore.Item> docs=DocumentStore.list(this);int totalRows=0,totalCols=0,mapped=0,validated=0,dups=0,empty=0,changed=0;for(DocumentStore.Item d:docs){totalRows+=d.rows;totalCols+=d.columns;dups+=d.duplicates;empty+=d.emptyCells;changed+=d.changedCells;int dm=0,dv=0;try{for(DataNormalizer.ColumnMapping m:DocumentStore.readMappings(this,d)){if(m.targetField!=null&&!m.targetField.isBlank()){mapped++;dm++;}if(m.humanValidated){validated++;dv++;}}}catch(Exception ignored){}s.add("• "+d.name+" — "+d.rows+" fiches, "+d.columns+" colonnes, qualité "+d.score+" %, "+dm+" champs cartographiés, "+dv+" validations humaines.");}s.add("Total : "+docs.size()+" catalogue(s), "+totalRows+" fiches, "+totalCols+" colonnes, "+mapped+" correspondances, "+validated+" validations humaines, "+changed+" corrections automatiques, "+empty+" cellules vides, "+dups+" doublons détectés.");s.add("");s.add("## Budget");s.add("Budget total : "+String.format(Locale.CANADA_FRENCH,"%.2f $",budget.getFloat("total",0f)));s.add("Aide théorique maximale : "+String.format(Locale.CANADA_FRENCH,"%.2f $",budget.getFloat("aid",0f)));s.add("Technologie / outils : "+budget.getString("tech","0")+" $");s.add("Sous-traitance / consultation : "+budget.getString("sub","0")+" $");s.add("Formation : "+budget.getString("training","0")+" $");s.add("Main-d’œuvre : "+budget.getString("labor","0")+" $");s.add("Administration : "+budget.getString("admin","0")+" $");s.add("Contingence : "+budget.getString("contingency","0")+" $");s.add("");s.add("## Équipe");s.add("Chef de projet : "+team.getString("chef","—"));s.add("Responsable données : "+team.getString("data","—"));s.add("Responsable technique : "+team.getString("tech","—"));s.add("Compétences : "+team.getString("competences","—"));s.add("Partenaires : "+team.getString("partenaires","—"));s.add("Fournisseurs : "+team.getString("fournisseurs","—"));s.add("Continuité : "+team.getString("continuite","—"));s.add("");s.add("## Échéancier");String[] phases={"Inventaire et sauvegarde","Cartographie","Nettoyage et normalisation","Validation humaine","Export et documentation","Partage / données ouvertes","Mesure et reddition"};for(int i=0;i<phases.length;i++)s.add("• "+phases[i]+" : "+timeline.getString("months"+i,"—")+" · "+timeline.getString("note"+i,"—")+(timeline.getBoolean("done"+i,false)?" [fait]":""));int checked=0;for(int i=0;i<14;i++)if(check.getBoolean("i"+i,false))checked++;s.add("");s.add("## État du dossier");s.add("Checklist : "+checked+" / 14");s.add("Pièces justificatives marquées disponibles : "+SupportingDocumentsActivity.completedCount(this)+" / 11");String[] pk={"quote","capacity","budget","timeline","data_plan","catalog_sample","mapping_audit","team","risks","open_data","official_forms"};String[] pl={"Devis fournisseur / estimation","Preuve de capacité interne","Budget détaillé","Échéancier","Plan de gestion des données","Échantillon catalogue","Audit de cartographie","Équipe et compétences","Registre des risques","Partage / données ouvertes","Formulaires officiels"};for(int i=0;i<pk.length;i++)s.add((pieces.getBoolean(pk[i],false)?"[OK] ":"[À FOURNIR] ")+pl[i]);s.add("");s.add("## Avertissement");s.add("Ce PDF est généré automatiquement à partir des données saisies dans l’application. Il ne constitue ni une certification, ni une décision d’admissibilité, ni une garantie de financement. Vérifier les formulaires, gabarits et règles officiels avant tout dépôt.");return s;}
 private List<String> wrap(String text,int max){ArrayList<String> out=new ArrayList<>();if(text==null||text.isEmpty()){out.add("");return out;}String[] words=text.split("\\s+");StringBuilder line=new StringBuilder();for(String w:words){if(line.length()>0&&line.length()+1+w.length()>max){out.add(line.toString());line.setLength(0);}if(line.length()>0)line.append(' ');line.append(w);}if(line.length()>0)out.add(line.toString());return out;}
}
